-- تحديث قوالب الملفات الأصلية حتى الدفعة الثالثة عشرة. نفذي بعد documents-schema.sql و document-templates-registry.sql.
-- لا يمس بيانات المتدربين أو سجلات الإصدار أو مواضع الأسماء المحفوظة.
BEGIN;
UPDATE public.trainee_document_templates SET enabled=FALSE WHERE template_id = 'all-batches-letter';
COMMIT;
SELECT batch_name,document_kind,document_type,image_path FROM public.trainee_document_templates WHERE enabled=TRUE ORDER BY batch_name,document_kind,document_type;
